const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const projectDir = root;
const gradlew = process.platform === "win32" ? "gradlew.bat" : "./gradlew";
const command = path.join(projectDir, gradlew);

const result = spawnSync(command, ["jsBrowserProductionWebpack", "--console=plain"], {
	cwd: projectDir,
	stdio: "inherit",
	env: Object.assign({}, process.env, {
		JAVA_HOME: process.env.JAVA_HOME || "/usr/lib/jvm/java-25-openjdk-amd64"
	})
});
if (result.error) {
	console.error(result.error);
	process.exit(1);
}
if (result.status !== 0) process.exit(result.status || 1);

const input = path.join(projectDir, "build/ca-kotlin/kotlin-webpack/js/productionExecutable/ca-kotlin.js");
const outputDir = path.join(root, "build/outputs/kotlin-js");
fs.mkdirSync(outputDir, { recursive: true });
const source = fs.readFileSync(input, "utf8")
	.replace(/\n?\/\/# sourceMappingURL=.*\n?$/, "")
	.trimEnd();
const header = "/* Generated by npm run kotlin:js; do not edit. */\n";
fs.writeFileSync(path.join(outputDir, "ca-kotlin.js"), header + source + ";\n");
const generated = path.join(root, "build/outputs/kotlin-js/Internal.kotlin.js");
fs.writeFileSync(generated, header + source + ";\n");
console.log("Kotlin/JS bundle -> " + path.join(outputDir, "ca-kotlin.js"));
console.log("Generated module -> " + generated);
